def f(g):
    h,w=len(g),len(g[0])
    rows={r for r in range(h) if len(set(g[r]))==1}
    cols={c for c in range(w) if len({g[r][c] for r in range(h)})==1}
    # line color = color of those full lines; accent = smallest color not present
    present={v for row in g for v in row}
    lines=[g[r][0] for r in rows]+[g[0][c] for c in cols]
    lc=lines[0]
    accent=min(v for v in range(10) if v not in present)
    return [[accent if (r in rows or c in cols) and g[r][c]==lc else v for c,v in enumerate(row)] for r,row in enumerate(g)]
